typedef enum
{
	PGRES_POLLING_FAILED = 0,
	PGRES_POLLING_READING,		/* These two indicate that one may	  */
	PGRES_POLLING_WRITING,		/* use select before polling again.   */
	PGRES_POLLING_OK,
	PGRES_POLLING_ACTIVE		/* unused; keep for awhile for backwards
								 * compatibility */
} PostgresPollingStatusType;

typedef enum
{
	PQTRANS_IDLE,
	PQTRANS_ACTIVE,
	PQTRANS_INTRANS,
	PQTRANS_INERROR,
	PQTRANS_UNKNOWN
} PGTransactionStatusType;

typedef enum
{
	PQERRORS_TERSE,
	PQERRORS_DEFAULT,
	PQERRORS_VERBOSE,
	PQERRORS_SQLSTATE
} PGVerbosity;

typedef enum
{
	PQSHOW_CONTEXT_NEVER,
	PQSHOW_CONTEXT_ERRORS,
	PQSHOW_CONTEXT_ALWAYS
} PGContextVisibility;

typedef enum
{
	PQPING_OK,
	PQPING_REJECT,
	PQPING_NO_RESPONSE,
	PQPING_NO_ATTEMPT
} PGPing;

typedef enum
{
	PQ_PIPELINE_OFF,
	PQ_PIPELINE_ON,
	PQ_PIPELINE_ABORTED
} PGpipelineStatus;

typedef struct pgNotify
{
	char	   *relname;
	int			be_pid;
	char	   *extra;
	/* Fields below here are private to libpq; apps should not use 'em */
	struct pgNotify *next;
} PGnotify;

typedef struct _PQprintOpt
{
	pqbool		header;
	pqbool		align;
	pqbool		standard;
	pqbool		html3;
	pqbool		expanded;
	pqbool		pager;
	char	   *fieldSep;
	char	   *tableOpt;
	char	   *caption;
	char	  **fieldName;
} PQprintOpt;

typedef struct _PQconninfoOption
{
	char	   *keyword;
	char	   *envvar;
	char	   *compiled;
	char	   *val;
	char	   *label;
	char	   *dispchar;
	int			dispsize;
} PQconninfoOption;

typedef struct
{
	int			len;
	int			isint;
	union
	{
		int	   *ptr;
		int			integer;
	}			u;
} PQArgBlock;

typedef struct pgresAttDesc
{
	char	   *name;
	Oid			tableid;
	int			columnid;
	int			format;
	Oid			typid;
	int			typlen;
	int			atttypmod;
} PGresAttDesc;

typedef enum
{
	PGEVT_REGISTER,
	PGEVT_CONNRESET,
	PGEVT_CONNDESTROY,
	PGEVT_RESULTCREATE,
	PGEVT_RESULTCOPY,
	PGEVT_RESULTDESTROY
} PGEventId;

typedef struct
{
	const PGresult *src;
	PGresult   *dest;
} PGEventResultCopy;

