// Generate a conninfo string (may be empty/garbage; libpq will parse/fail accordingly)
std::string conninfo_str = FUZZ_PARAM_STR();
const char *conninfo = conninfo_str.c_str();

// Start a nonblocking connection attempt; may return NULL on OOM
PGconn *conn = PQconnectStart(conninfo);
if (!conn) { FUZZ_BAIL(); }

// Mark that this connection was started via PQconnectStart so PQconnectPoll is allowed later
FUZZ_SET_ATTR_INT(conn, "conn_started", 1);

// Do NOT poll here to avoid network/blocking. The fuzzer will decide when/if to poll.
// Validation: We return a non-null PGconn* with an attribute indicating start state; no blocking calls performed.

// Build small NULL-terminated keyword/value arrays with equal lengths
const int kMaxPairs = 3;
int pairCount = (int)(*FUZZ_PARAM(unsigned int) % (kMaxPairs + 1));

// Storage for pointers; ensure final NULL terminator
const char *keywords_local[kMaxPairs + 1];
const char *values_local[kMaxPairs + 1];
for (int i = 0; i < pairCount; ++i) {
    std::string k = FUZZ_PARAM_STR();
    std::string v = FUZZ_PARAM_STR();
    // Use c_str() to ensure NUL-terminated C strings valid for the duration of this call
    keywords_local[i] = k.c_str();
    values_local[i] = v.c_str();
}
keywords_local[pairCount] = nullptr;
values_local[pairCount] = nullptr;

int expand_dbname = (int)(*FUZZ_PARAM(unsigned int) & 1);

PGconn *conn = PQconnectStartParams(keywords_local, values_local, expand_dbname);
if (!conn) { FUZZ_BAIL(); }

// Mark as connect-started for use by PQconnectPoll
FUZZ_SET_ATTR_INT(conn, "conn_started", 1);

// Validation: Arrays are NULL-terminated and lengths match; conn is returned with start-state attribute.

// Enforce that this PGconn came from PQconnectStart*
int started = FUZZ_GET_ATTR_INT(conn, "conn_started");
if (!started) { FUZZ_BAIL(); }

// Advance the nonblocking handshake once; caller/fuzzer may call again later
PostgresPollingStatusType st = PQconnectPoll(conn);
(void)st; // We don't busy-wait here; just exercise the API once.

// Validation: Only called on a connection previously started; connection is returned to pool for further progress.

// Close and free the PGconn; safe to pass even if connection failed or is partially initialized
PQfinish(conn);

// Validation: Ownership transferred to libpq and object is not returned; avoids double-free.

// Retrieve a newly allocated array of PQconninfoOption
PQconninfoOption *opts = PQconndefaults();
if (!opts) { FUZZ_BAIL(); }

// Track origin so only PQconninfoFree frees it
FUZZ_SET_ATTR_INT(opts, "conninfo_array", 1);

// Validation: Non-null array returned and attributed for proper freeing later.

// Parse a conninfo string to an array
std::string conninfo_str = FUZZ_PARAM_STR();
const char *conninfo = conninfo_str.c_str();
char *errmsg = nullptr;

PQconninfoOption *opts = PQconninfoParse(conninfo, &errmsg);

// If libpq produced an error message, free it using PQfreemem
if (errmsg) {
    PQfreemem(errmsg);
}

if (!opts) { FUZZ_BAIL(); }

// Attribute to ensure correct freeing path
FUZZ_SET_ATTR_INT(opts, "conninfo_array", 1);

// Validation: We free optional errmsg and publish the resulting array for later PQconninfoFree.

// Obtain the options actually in use; may return NULL if not connected
PQconninfoOption *opts = PQconninfo(conn);
if (!opts) {
    // If not available, bail to avoid passing a null output object to the pool
    FUZZ_BAIL();
}

// Track origin for proper freeing
FUZZ_SET_ATTR_INT(opts, "conninfo_array", 1);

// Validation: Only publish non-null arrays; the input conn is returned unchanged.

// Ensure this pointer came from a libpq conninfo-producing function
int is_arr = FUZZ_GET_ATTR_INT(opts, "conninfo_array");
if (!is_arr) { FUZZ_BAIL(); }

PQconninfoFree(opts);

// Validation: Pointer provenance checked via attribute; no outputs to avoid UAF.

// Begin an asynchronous reset on an existing connection
int rc = PQresetStart(conn);
(void)rc; // rc is an int status; regardless, we allow subsequent polling

// Mark that reset has been started so PQresetPoll is gated
FUZZ_SET_ATTR_INT(conn, "reset_started", 1);

// Validation: We do not block; we only tag the connection for subsequent PQresetPoll calls.

// Must only poll after PQresetStart
int reset_started = FUZZ_GET_ATTR_INT(conn, "reset_started");
if (!reset_started) { FUZZ_BAIL(); }

