// Track association to its parent connection
FUZZ_SET_ATTR_PTR(cancel, "parent_conn", (void*)conn);

// Validation: Non-null PGcancel is produced and linked to its PGconn; both returned to pool.

// Free the PGcancel object
PQfreeCancel(cancel);

// Validation: Freed exactly once; not returned to pool to prevent UAF.

// Provide an error buffer; size reflects capacity
char errbuf[256];
int ret = PQcancel(cancel, errbuf, (int)sizeof(errbuf));
(void)ret; // We don't assert success; network/state dependent

// Validation: Passed a valid buffer and size; PGcancel is not freed, so it's returned to the pool.

