(void)opts;

// Validation: Getter exercised; input connection returned.

// Query overall connection status
ConnStatusType st = PQstatus(conn);
(void)st;

// Validation: Status getter called; connection left intact.

// Query transaction status for this connection
PGTransactionStatusType txst = PQtransactionStatus(conn);
(void)txst;

// Validation: Getter exercised; connection preserved.

// Provide a parameter name (must be non-NULL); value may be NULL if unknown
std::string pname = FUZZ_PARAM_STR();
const char *paramName = pname.c_str();
const char *val = PQparameterStatus(conn, paramName);
(void)val;

// Validation: Non-NULL parameter name used; connection returned to pool.

// Retrieve negotiated protocol version (integer)
int pv = PQprotocolVersion(conn);
(void)pv;

// Validation: Getter exercised; connection preserved.

// Retrieve server version as integer; may be 0 if unknown
int sv = PQserverVersion(conn);
(void)sv;

// Validation: Getter exercised; connection returned unchanged.

// Retrieve most recent error message string; never free the returned pointer
