(void)emsg;

// Validation: Getter exercised; connection preserved.

// Retrieve underlying socket fd, or -1 if not available
int sockfd = PQsocket(conn);
(void)sockfd;

// Validation: Getter exercised; connection returned.

// Retrieve backend PID; may be 0 or negative if not connected depending on libpq
int pid = PQbackendPID(conn);
(void)pid;

// Validation: Getter exercised; connection preserved.

// Retrieve pipeline mode status for this connection
PGpipelineStatus pst = PQpipelineStatus(conn);
(void)pst;

// Validation: Getter exercised; connection returned for reuse.

// Check whether authentication required a password but none was supplied
int needs = PQconnectionNeedsPassword(conn);
(void)needs;

// Validation: Getter exercised; connection preserved.

// Check whether a password was used for this connection
int used = PQconnectionUsedPassword(conn);
(void)used;

// Validation: Getter exercised; connection preserved.

// Retrieve current client encoding id
int enc = PQclientEncoding(conn);
(void)enc;

// Validation: Getter exercised; connection preserved.

// Choose an encoding name. Prefer a plausible one via pg_encoding_to_char from a fuzzed id
int encId = (int)(*FUZZ_PARAM(unsigned int) % 300); // pick within a small range
const char *encName = pg_encoding_to_char(encId);
// Call setter; success depends on validity and server settings
int rc = PQsetClientEncoding(conn, encName);
(void)rc;

// Validation: Provided a non-NULL encoding name string; connection returned regardless of outcome.

// Check if SSL/TLS is in use on this connection
int ssl = PQsslInUse(conn);
(void)ssl;

// Validation: Getter exercised; connection preserved for further operations.

// Provide a structure name to query (library-specific; may yield NULL)
std::string sname = FUZZ_PARAM_STR();
const char *struct_name = sname.c_str();

void *p = PQsslStruct(conn, struct_name);
(void)p; // May be NULL; do not dereference

// Validation: We supplied a C string and exercised the API; the input conn remains valid and is returned.

// Sometimes query the global-detection attribute with NULL conn, otherwise use the provided conn
int use_null_conn = (int)(*FUZZ_PARAM(unsigned int) & 1);
const char *attr_name = (use_null_conn ? "library" : FUZZ_PARAM_STR().c_str());

const char *val = PQsslAttribute(use_null_conn ? nullptr : conn, attr_name);
(void)val; // May be NULL if unsupported/unknown

// Validation: Attribute name is non-NULL; if NULL-conn path taken we restrict to "library"; conn is returned unchanged.

// Retrieve the NULL-terminated list of attribute names for this connection
const char *const *names = PQsslAttributeNames(conn);
// Iterate a few entries defensively without heavy work
if (names) {
