// Validation: We handled both NULL and non-NULL lists safely; conn is returned to the pool.

// Obtain TLS-implementation-specific SSL pointer (OpenSSL) or NULL
void *ssl = PQgetssl(conn);
(void)ssl; // Do not assume non-NULL or dereference

// Validation: Getter exercised without assumptions; conn is returned.

// Randomly decide whether libpq should initialize OpenSSL on its own
int do_init = (int)(*FUZZ_PARAM(unsigned int) & 1);
