    "host", "hostaddr", "port", "dbname", "user", "password", "passfile",
    "connect_timeout", "client_encoding", "options", "application_name",
    "fallback_application_name", "sslmode", "sslrootcert", "sslcert", "sslkey",
    "sslcrl", "requirepeer", "krbsrvname", "gsslib", "service", "keepalives",
    "keepalives_idle", "keepalives_interval", "keepalives_count", "target_session_attrs",
    "channel_binding", "require_auth", "connect_timeout", "tty"
]

