    "localhost", "127.0.0.1", "::1", "example.local", "db.internal",
    "[::1]",  # URI literal IPv6 style
]
PORTS = ["5432", "5433", "6543", "1", "65535"]
DBNAMES = ["postgres", "template1", "mydb", "test_db", "db-αβγ", "" ]
USERS = ["postgres", "alice", "bob", "user123", "" ]
APPNAMES = ["psql", "libpq-fuzz", "迁移工具", "app_with_spaces"]
ENCODINGS = ["UTF8", "LATIN1", "SQL_ASCII", "WIN1252"]
BOOLS = ["0", "1", "true", "false", "on", "off"]

# Helpers

def _rand(r: random.Random, seq):
    return seq[r.randrange(len(seq))]

def _rand_ascii(r: random.Random, min_len=3, max_len=16):
    n = r.randint(min_len, max_len)
    s = ''.join(r.choice(string.ascii_letters + string.digits + "_-.") for _ in range(n))
    return s

def _rand_utf8(r: random.Random, min_len=3, max_len=12):
    # Include some multibyte characters likely valid in UTF-8
    pool = list("абвгдежзийклмнопqrstuv我爱数据ñöäéèçΔλΩ") + list(string.ascii_letters + string.digits + "_- ")
    n = r.randint(min_len, max_len)
    return ''.join(r.choice(pool) for _ in range(n))

def _maybe_quote(r: random.Random, v: str) -> str:
    # libpq conninfo allows single-quoted values; quotes inside escaped with \
    if r.random() < 0.5 or (' ' in v or '=' in v or v == ""):
        vq = v.replace("'", r.choice(["''", "'"]))  # double up or leave as-is (still valid-ish for parser tests)
        return f"'{vq}'"
    return v

