    return f"{k}={_maybe_quote(r, v)}"

def build_keyword_style(r: random.Random) -> str:
    parts: List[str] = []
    # Always include a few core keys
    parts.append(_kv("host", _rand(r, HOSTS + ["localhost,127.0.0.1"]), r))  # multi-host string
    parts.append(_kv("port", _rand(r, PORTS), r))
    parts.append(_kv("dbname", _rand(r, DBNAMES + [_rand_utf8(r)]), r))
    parts.append(_kv("user", _rand(r, USERS + [_rand_utf8(r)]), r))

    # Optionally add many others
    if r.random() < 0.8:
        parts.append(_kv("application_name", _rand(r, APPNAMES + [_rand_utf8(r)]), r))
    if r.random() < 0.6:
        parts.append(_kv("client_encoding", _rand(r, ENCODINGS), r))
    if r.random() < 0.7:
        parts.append(_kv("sslmode", _rand(r, SSL_MODES), r))
    if r.random() < 0.5:
        parts.append(_kv("target_session_attrs", _rand(r, TARGET_SESSION_ATTRS), r))
    if r.random() < 0.4:
        parts.append(_kv("channel_binding", _rand(r, CHANNEL_BINDING), r))
    if r.random() < 0.5:
        parts.append(_kv("connect_timeout", str(r.randint(0, 120)), r))
    if r.random() < 0.4:
        parts.append(_kv("password", _rand_utf8(r, 0, 16), r))
    if r.random() < 0.3:
        parts.append(_kv("options", f"-c search_path={_rand_ascii(r)}", r))
    if r.random() < 0.3:
        parts.append(_kv("keepalives", _rand(r, BOOLS), r))
    if r.random() < 0.3:
        parts.append(_kv("keepalives_idle", str(r.randint(1, 7200)), r))
    if r.random() < 0.3:
        parts.append(_kv("keepalives_interval", str(r.randint(1, 300)), r))
    if r.random() < 0.3:
        parts.append(_kv("keepalives_count", str(r.randint(1, 20)), r))

    # Random extra unknown keywords to exercise parser tolerance
    for _ in range(r.randint(0, 3)):
        parts.append(_kv(_rand_ascii(r), _rand_utf8(r, 0, 10), r))

    # Random spacing, including multiple spaces
    sep = _rand(r, [" ", "  ", "\t"]) 
    s = sep.join(parts)
    # Optionally prefix/suffix spaces
    if r.random() < 0.5:
        s = _rand(r, [" ", "\t"]) + s
    if r.random() < 0.5:
        s = s + _rand(r, [" ", "\t"]) 
    return s


def build_uri_style(r: random.Random) -> str:
    # postgresql://[user[:password]@][host][:port][,host2[:port2]]/[dbname][?param1=value1&...]
    scheme = _rand(r, ["postgresql", "postgres"])  # both accepted

    # Authority
    userinfo = ""
    if r.random() < 0.9:
        u = _rand(r, USERS + [_rand_utf8(r)])
        if r.random() < 0.6:
            p = _rand_utf8(r, 0, 12)
            userinfo = f"{u}:{p}@"
        else:
            userinfo = f"{u}@"

    def hostport() -> str:
        h = _rand(r, HOSTS)
        # Trim URI-style IPv6 brackets duplication
        if h.startswith("[") and h.endswith("]"):
            hp = h
        else:
            hp = h
        if r.random() < 0.7:
            hp += f":{_rand(r, PORTS)}"
        return hp

    # Possibly multi-host for libpq's URI multi-host syntax
    hp_list = [hostport() for _ in range(r.randint(1, 3))]
    authority = ",".join(hp_list)

    # Path (dbname)
    if r.random() < 0.85:
        db = _rand(r, DBNAMES + [_rand_utf8(r)])
    else:
        db = ""

    # Query params
    params: List[Tuple[str, str]] = []
    # Add a mix of known and unknown params
    if r.random() < 0.7:
        params.append(("sslmode", _rand(r, SSL_MODES)))
    if r.random() < 0.5:
        params.append(("target_session_attrs", _rand(r, TARGET_SESSION_ATTRS)))
    if r.random() < 0.5:
        params.append(("application_name", _rand(r, APPNAMES + [_rand_utf8(r)])))
    if r.random() < 0.4:
        params.append(("client_encoding", _rand(r, ENCODINGS)))
    if r.random() < 0.4:
        params.append(("connect_timeout", str(r.randint(0, 120))))
    # Extras
    for _ in range(r.randint(0, 3)):
        params.append((_rand_ascii(r), _rand_utf8(r, 0, 10)))

    from urllib.parse import quote

    def enc(v: str) -> str:
        # Percent-encode minimally; keep safe chars but ensure UTF-8 handling
        return quote(v, safe="-._~@$")

    q = ""
    if params:
        q = "?" + "&".join(f"{enc(k)}={enc(v)}" for k, v in params)

    path = "/" + enc(db) if db != "" or r.random() < 0.5 else ""
    uri = f"{scheme}://{userinfo}{authority}{path}{q}"
    return uri


def build_service_style(r: random.Random) -> str:
    # service keyword triggers service file lookup; still a valid conninfo
    parts = [
        _kv("service", _rand(r, ["pgservice", "default", _rand_ascii(r)]), r),
    ]
    # Maybe provide overrides
    if r.random() < 0.7:
        parts.append(_kv("application_name", _rand(r, APPNAMES), r))
    if r.random() < 0.5:
        parts.append(_kv("sslmode", _rand(r, SSL_MODES), r))
    return " ".join(parts)


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose a style with weighted probabilities
    style = r.random()
    if style < 0.5:
        s = build_keyword_style(r)
    elif style < 0.85:
        s = build_uri_style(r)
    else:
        s = build_service_style(r)

    # Ensure length bounds and NUL-terminated expectations from C side
    # We provide bytes without explicit NUL since C++ std::string adds NUL.
    data = s.encode('utf-8')
    if len(data) > 4096:
        data = data[:4096]
    return data

import random
import struct
from typing import List, Tuple

# This generator produces a bytes buffer intended to seed FUZZ_PARAM_STR/FUZZ_PARAM_FILENAME
# in fuzzers that exercise libpq keyword/value connection parameter arrays
# (e.g., PQconnectStartParams, PQpingParams).
#
# Strategy:
# - Emit a sequence of NUL-terminated strings concatenated together.
# - Strings include valid libpq connection keywords, realistic values, and edge-case variations.
# - The fuzzer will slice these as FUZZ_PARAM_STR calls; providing a rich pool increases coverage.
# - Keep within 4096 bytes.
#
# Keywords chosen from libpq conninfo options (subset, common and interesting):
#   host, hostaddr, port, dbname, user, password, sslmode, sslcert, sslkey, sslrootcert,
#   connect_timeout, application_name, options, service, requiressl, keepalives, keepalives_idle,
#   keepalives_interval, keepalives_count, gssencmode, target_session_attrs, client_encoding
#
# Values include: typical, boundary, and special forms (IPv4/IPv6, UNIX socket paths, numbers,
# quoted strings, URIs, empty, very long, unusual encodings, and booleans).

MAX_TOTAL = 4096

KEYWORDS = [
    "host", "hostaddr", "port", "dbname", "user", "password", "sslmode",
    "sslcert", "sslkey", "sslrootcert", "connect_timeout", "application_name",
    "options", "service", "requiressl", "keepalives", "keepalives_idle",
    "keepalives_interval", "keepalives_count", "gssencmode",
    "target_session_attrs", "client_encoding"
]

SSL_MODES = ["disable", "allow", "prefer", "require", "verify-ca", "verify-full"]
GSS_MODES = ["disable", "prefer", "require"]
TSA_VALUES = ["any", "read-write", "read-only", "primary", "standby"]
BOOLEAN = ["0", "1", "true", "false", "on", "off", "yes", "no"]
ENCODINGS = [
    "UTF8", "SQL_ASCII", "LATIN1", "WIN1252", "SJIS", "BIG5", "EUC_JP",
]

IPV4S = ["127.0.0.1", "0.0.0.0", "192.168.1.1", "10.0.0.1"]
IPV6S = ["::1", "2001:db8::1", "fe80::1%lo0", "::ffff:127.0.0.1"]
HOSTS = ["localhost", "db", "postgres", "example.com"]
UNIX_SOCKS = ["/var/run/postgresql", "/tmp", "/var/pgsql_socket"]
DBS = ["postgres", "template1", "test", "fuzz", "" ]
USERS = ["postgres", "pg", "user", "alice", "bob"]
PASSWORDS = ["", "secret", "p@ss w\x00rd", "'quoted'", "\\escaped\\", "长密码"]
APPNAMES = ["psql", "libpq-fuzz", "app", "測試應用", "a" * 64]

# Helper to produce a reasonable value for a given keyword

def value_for_keyword(rng: random.Random, key: str) -> str:
    k = key.lower()
    if k == "host":
        choice = rng.randrange(4)
        if choice == 0:
            return rng.choice(HOSTS)
        elif choice == 1:
            return rng.choice(IPV4S)
        elif choice == 2:
            return rng.choice(IPV6S)
        else:
            return rng.choice(UNIX_SOCKS)
    if k == "hostaddr":
        return rng.choice(IPV4S + IPV6S)
    if k == "port":
        return str(rng.choice(["", "5432", "1", "65535", str(rng.randint(2, 65534))]))
    if k == "dbname":
        return rng.choice(DBS + ["db-" + str(rng.randint(0, 999)), '"QuotedDB"'])
    if k == "user":
        return rng.choice(USERS)
    if k == "password":
        return rng.choice(PASSWORDS + ["\"pw with spaces\"", "$ecret", "{md5}deadbeef"]) 
    if k == "sslmode":
        return rng.choice(SSL_MODES)
    if k in ("sslcert", "sslkey", "sslrootcert"):
        # Provide plausible file paths and edge-cases
        base = rng.choice(["/etc/ssl/certs", "/etc/ssl/private", "/tmp", "C:/certs", "relative"]) 
        name = rng.choice(["client.crt", "client.key", "root.crt", ".hidden", "cafile.pem"]) 
        return base.rstrip("/") + "/" + name
    if k == "connect_timeout":
        return rng.choice(["", "1", "2", "5", "10", "60", str(rng.randint(0, 600))])
    if k == "application_name":
        return rng.choice(APPNAMES)
    if k == "options":
        return rng.choice(["-c statement_timeout=1000", "-c search_path=public", "", "-c work_mem=64MB"]) 
    if k == "service":
        return rng.choice(["", "pgservice", "prod", "dev"]) 
    if k == "requiressl":
        return rng.choice(BOOLEAN)
    if k in ("keepalives", "keepalives_idle", "keepalives_interval", "keepalives_count"):
        return rng.choice(["", "0", "1", "5", "10", "30", str(rng.randint(0, 120))])
    if k == "gssencmode":
        return rng.choice(GSS_MODES)
    if k == "target_session_attrs":
        return rng.choice(TSA_VALUES)
    if k == "client_encoding":
        return rng.choice(ENCODINGS)
    # Fallback: generic text
    return "val" + str(rng.randint(0, 9999))

# Generate a set of key/value pairs with various interesting permutations:
# - valid known keys
# - mixed case keys (case-insensitive handling)
# - duplicate keys (later wins in libpq), included to exercise code paths
# - unknown keys to exercise parsing fallback

def build_pairs(rng: random.Random) -> List[Tuple[str, str]]:
    pairs: List[Tuple[str, str]] = []

    # Choose a base size
    count = rng.randint(1, 10)

    # Ensure some foundational keys are present occasionally
    foundation = ["host", "port", "user", "dbname", "sslmode"]
    rng.shuffle(foundation)
    for k in foundation[:rng.randint(2, len(foundation))]:
        v = value_for_keyword(rng, k)
        # introduce mixed case randomly
        if rng.random() < 0.4:
            k = _mixed_case(rng, k)
        pairs.append((k, v))

    # Add random known keys
    for _ in range(count):
        k = rng.choice(KEYWORDS)
        v = value_for_keyword(rng, k)
        if rng.random() < 0.4:
            k = _mixed_case(rng, k)
        pairs.append((k, v))

    # Add some unknown/experimental keys
    for _ in range(rng.randint(0, 3)):
        k = "unknown_" + str(rng.randint(0, 100))
        v = rng.choice(["", "foo", "123", "bar=baz", "true"]) 
        pairs.append((k, v))

    # Optional duplicates to test last-one-wins behavior
    if rng.random() < 0.7:
        dupk = rng.choice(KEYWORDS)
        pairs.append((dupk, value_for_keyword(rng, dupk)))

    # Possibly add URI-style dbname as a key
    if rng.random() < 0.5:
        uri = build_uri(rng)
        pairs.append(("dbname", uri))

    # Possibly add service-only minimal set
    if rng.random() < 0.3:
        pairs.append(("service", rng.choice(["prod", "dev", "qa"])) )

    return pairs


def _mixed_case(rng: random.Random, s: str) -> str:
    return ''.join(c.upper() if rng.random() < 0.5 else c.lower() for c in s)


def build_uri(rng: random.Random) -> str:
    # Build a connection URI (valid, simple forms)
    # postgresql://[user[:password]@][host][:port]/[dbname]?param=value
    scheme = rng.choice(["postgresql://", "postgres://"])  # both accepted
    auth = ""
    if rng.random() < 0.8:
        user = rng.choice(USERS)
        if rng.random() < 0.6:
            pwd = rng.choice(PASSWORDS).replace("@", "%40")
            auth = f"{user}:{pwd}@"
        else:
            auth = f"{user}@"
    host = rng.choice(HOSTS + IPV4S)
    if ":" in host and not host.startswith('['):
        host = f"[{host}]"  # bracket IPv6 if chosen (though we selected only hosts/IPv4)
    port = ":" + str(rng.randint(1, 65535)) if rng.random() < 0.6 else ""
    db = "/" + rng.choice(DBS + ["uri_db"]) if rng.random() < 0.9 else "/"
    # add a couple of parameters
    params = []
    if rng.random() < 0.6:
        params.append("sslmode=" + rng.choice(SSL_MODES))
    if rng.random() < 0.5:
        params.append("application_name=" + rng.choice(APPNAMES))
    if rng.random() < 0.4:
        params.append("connect_timeout=" + str(rng.randint(0, 60)))
    query = ("?" + "&".join(params)) if params else ""
    return scheme + auth + host + port + db + query


def _nul_terminated_chunks(chunks: List[bytes]) -> bytes:
    # Join with NUL terminators; fuzz infra will take substrings as C strings.
    return b"\x00".join(chunks) + b"\x00"


def _encode(s: str) -> bytes:
    # Encode to UTF-8; replace NULs inside values with safe substitute since C strings end at NUL.
    # We keep behavior valid by replacing embedded NUL with space.
    s = s.replace("\x00", " ")
    return s.encode("utf-8", errors="replace")


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Build pairs
    pairs = build_pairs(rng)

    # Additionally, provide some standalone strings that are commonly used by conninfo parsing
    extras: List[str] = []
    # single keywords
    extras.extend(rng.sample(KEYWORDS, k=min(len(KEYWORDS), rng.randint(3, 7))))
    # standalone values likely used for filenames or numeric fields
    extras.extend([
        rng.choice(IPV4S), rng.choice(IPV6S), rng.choice(UNIX_SOCKS),
        "5432", "0", "65535", "", rng.choice(SSL_MODES), rng.choice(TSA_VALUES)
    ])
    # a full conninfo string to seed FUZZ_PARAM_STR in one go
    if rng.random() < 0.7:
        conninfo_parts = []
        # choose a subset of pairs for the conninfo string
        for k, v in rng.sample(pairs, k=min(len(pairs), rng.randint(3, min(8, len(pairs))))):
            # Quote only when necessary (spaces or special chars)
            if any(ch.isspace() for ch in v) or any(ch in v for ch in "'\"\\"):
                qv = "'" + v.replace("'", "\\'") + "'"
            else:
                qv = v
            conninfo_parts.append(f"{k}={qv}")
        extras.append(" ".join(conninfo_parts))

    # Prepare the byte chunks: interleave key/value pairs and extras
    chunks: List[bytes] = []

    # Encode pairs as separate strings to feed FUZZ_PARAM_STR
    for k, v in pairs:
        chunks.append(_encode(k))
        chunks.append(_encode(v))

    for s in extras:
        chunks.append(_encode(s))

    payload = _nul_terminated_chunks(chunks)

    # Truncate to MAX_TOTAL while preserving last NUL termination
    if len(payload) > MAX_TOTAL:
        payload = payload[:MAX_TOTAL-1] + b"\x00"

    return payload

import random
import string
from typing import List

# This generator produces valid, interesting ASCII identifier-like C strings
# and small files paths for the stubs that request FUZZ_PARAM_STR/FUZZ_PARAM_FILENAME.
# Targeted APIs: PQparameterStatus, PQsslStruct, PQsslAttribute, PQprepare,
# PQexecPrepared, PQsendPrepare, PQsendQueryPrepared, PQfnumber,
# PQdescribePrepared, PQdescribePortal, PQsendDescribePrepared,
# PQsendDescribePortal, PQsetResultAttrs, PQprint, PQdisplayTuples,
# PQregisterEventProc.
#
# Strategy:
# - Emit a sequence of NUL-terminated strings concatenated together. The harness
#   extracts them in order for FUZZ_PARAM_STR.
# - Include a few context-appropriate tokens to exercise meaningful code paths
#   (e.g., SQL snippets, common SSL attribute/struct names, libpq-known GUCs,
#   statement/portal names, separators, and plausible filenames).
# - Keep all content printable ASCII and <= 4096 bytes total.
#
# Layout of the buffer (all components are ASCII and NUL-terminated):
# [S list...] where S covers:
#   1) Parameter names for PQparameterStatus (server_version, client_encoding, ...)
#   2) SSL struct names for PQsslStruct ("SSL", "X509") and random variants
#   3) SSL attribute names for PQsslAttribute (cipher, bits, protocol, ...)
#   4) Prepared statement names (identifier-like)
#   5) SQL queries for prepare/send/execPrepared (simple SELECT/INSERT with params)
#   6) Param values for prepared execution (a few strings, numbers, binary-like text)
#   7) Field names for PQfnumber
#   8) Portal names
#   9) Separators/table options/captions for printing functions
#  10) Filenames for PQprint/PQdisplayTuples (treated as C strings by harness)
#  11) Registration names for PQregisterEventProc
#  12) Extra random identifiers to ensure supply doesn't run out
#
# The harness may interleave consumption across multiple stubs; providing a rich
# pool of strings increases the chance that each call receives a semantically
# meaningful value.

MAX_TOTAL = 4096

# Common token pools
PARAMETER_STATUS_KEYS = [
    "server_version", "server_encoding", "client_encoding", "DateStyle",
    "TimeZone", "integer_datetimes", "is_superuser", "session_authorization",
    "standard_conforming_strings", "application_name", "search_path",
]

SSL_STRUCT_NAMES = [
    # Common OpenSSL handle names used by PQsslStruct
    "SSL", "X509", "SSL_SESSION", "SSL_CTX", "peer_certificate",
]

SSL_ATTRIBUTE_NAMES = [
    # Attributes recognized by libpq on OpenSSL builds
    "library", "key_bits", "cipher", "cipher_bits", "protocol",
    "compression", "ssl_renegotiation_limit", "ssl_in_use",
]

FIELD_NAMES_COMMON = [
    "id", "name", "value", "created_at", "updated_at", "data",
]

# A few simple, valid SQL statements covering prepare/execute with up to 3 params
SQL_TEMPLATES = [
    ("SELECT 1", 0),
    ("SELECT $1", 1),
    ("SELECT $1, $2", 2),
    ("SELECT $1::int + $2::int", 2),
    ("SELECT $1::text || '-' || $2::text || '-' || $3::text", 3),
    ("INSERT INTO foo(id, name) VALUES($1::int, $2::text)", 2),
    ("PREPARE pst(int, text) AS SELECT $1, $2", 0),  # harmless; prepare name separate
]

SEPARATORS = [",", "|", "\t", " :: ", " ", ":", ";", ", "]
TABLE_OPTS = [
    "ALIGN=LEFT", "BORDER=1", "CELLSPACING=0", "CELLBORDER=1", "WIDTH=80%",
]
CAPTIONS = ["Results", "Report", "Summary", "Data", "Output"]

# Filenames: the harness creates files at returned paths; use safe relative names
FILENAMES = [
    "out.txt", "print.html", "tuples.txt", "res.bin", "a.log",
]

def rand_ident(rng: random.Random, min_len=1, max_len=24) -> str:
    first_chars = string.ascii_letters + '_'
    other_chars = string.ascii_letters + string.digits + '_'
    n = rng.randint(min_len, max_len)
    s = rng.choice(first_chars)
    s += ''.join(rng.choice(other_chars) for _ in range(n - 1))
    return s

def rand_ascii(rng: random.Random, min_len=0, max_len=48) -> str:
    chars = string.ascii_letters + string.digits + string.punctuation + ' '
    n = rng.randint(min_len, max_len)
    return ''.join(rng.choice(chars) for _ in range(n))

def sql_and_params(rng: random.Random):
    sql, nparams_base = rng.choice(SQL_TEMPLATES)
    # Occasionally vary param count within 0..3 regardless of template to exercise stubs
    if rng.random() < 0.3:
        nparams = rng.randint(0, 3)
    else:
        nparams = nparams_base
    # Generate text param values; stubs decide formats/lengths
    params: List[str] = []
    for i in range(nparams):
        choice = rng.random()
        if choice < 0.3:
            params.append(str(rng.randint(-10_000, 10_000)))
        elif choice < 0.6:
            params.append(rand_ident(rng, 1, 16))
        elif choice < 0.85:
            params.append(rand_ascii(rng, 0, 24))
        else:
            # Pseudo-binary-looking but still printable
            params.append(''.join(rng.choice('0123456789ABCDEF') for _ in range(rng.randint(0, 32))))
    return sql, params

def make_cstring(s: str) -> bytes:
    # Ensure no embedded NUL; replace with space if any
    s = s.replace('\x00', ' ')
    return s.encode('ascii', 'ignore') + b'\x00'

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    parts: List[bytes] = []
    total = 0

    def add_str(s: str):
        nonlocal total
        b = make_cstring(s)
        if total + len(b) > MAX_TOTAL:
            return False
        parts.append(b)
        total += len(b)
        return True

    # 1) ParameterStatus keys (mix fixed and random plausible names)
    keys = PARAMETER_STATUS_KEYS[:]
    rng.shuffle(keys)
    for k in keys[:rng.randint(3, min(7, len(keys)))]:
        if not add_str(k):
            return b''.join(parts)
    for _ in range(rng.randint(1, 3)):
        if not add_str(rand_ident(rng)):
            return b''.join(parts)

    # 2) SSL struct names
    ssn = SSL_STRUCT_NAMES[:]
    rng.shuffle(ssn)
    for name in ssn[:rng.randint(2, min(4, len(ssn)))]:
        if not add_str(name):
            return b''.join(parts)
    # Add a few random variants like "SSL*" or lowercase
    for _ in range(rng.randint(1, 3)):
        base = rng.choice(["SSL", "X509", rand_ident(rng)])
        suffix = rng.choice(["_CTX", "_SESSION", "_OBJ", "", "Handle"])
        if not add_str((base + suffix).lower() if rng.random() < 0.5 else base + suffix):
            return b''.join(parts)

    # 3) SSL attribute names
    attrs = SSL_ATTRIBUTE_NAMES[:]
    rng.shuffle(attrs)
    for a in attrs[:rng.randint(3, min(6, len(attrs)))]:
        if not add_str(a):
            return b''.join(parts)

    # 4) Prepared statement names
    for _ in range(rng.randint(2, 5)):
        if not add_str(rand_ident(rng)):
            return b''.join(parts)

    # 5) SQL queries and 6) params
    for _ in range(rng.randint(2, 5)):
        sql, params = sql_and_params(rng)
        if not add_str(sql):
            return b''.join(parts)
        for p in params:
            if not add_str(p):
                return b''.join(parts)

    # 7) Field names for PQfnumber
    for f in FIELD_NAMES_COMMON:
        if not add_str(f):
            return b''.join(parts)
    for _ in range(rng.randint(1, 3)):
        if not add_str(rand_ident(rng)):
            return b''.join(parts)

    # 8) Portal names
    for _ in range(rng.randint(1, 3)):
        if not add_str("portal_" + rand_ident(rng)):
            return b''.join(parts)

    # 9) Printing options: separators, table options, captions
    for sep in rng.sample(SEPARATORS, k=min(len(SEPARATORS), rng.randint(2, 5))):
        if not add_str(sep):
            return b''.join(parts)
    for opt in rng.sample(TABLE_OPTS, k=min(len(TABLE_OPTS), rng.randint(1, 3))):
        if not add_str(opt):
            return b''.join(parts)
    for cap in rng.sample(CAPTIONS, k=min(len(CAPTIONS), rng.randint(1, 3))):
        if not add_str(cap):
            return b''.join(parts)

    # 10) Filenames
    # Include some base names and a few random variants/suffixes
    for fn in rng.sample(FILENAMES, k=min(len(FILENAMES), rng.randint(2, 5))):
        if not add_str(fn):
            return b''.join(parts)
    for _ in range(rng.randint(1, 3)):
        if not add_str(rand_ident(rng, 3, 12) + rng.choice([".txt", ".log", ".html", ".bin"])):
            return b''.join(parts)

    # 11) Registration names for PQregisterEventProc
    for _ in range(rng.randint(2, 4)):
        if not add_str("reg_" + rand_ident(rng)):
            return b''.join(parts)

    # 12) Extra random identifiers to ensure supply
    for _ in range(rng.randint(5, 12)):
        if not add_str(rand_ident(rng)):
            break

    return b''.join(parts)

import random
import string
from typing import List

# Generator for libpq COPY IN deprecated line protocol (PQputline)
# Data type: text line (NUL-terminated C string). We must return bytes that
# FUZZ_PARAM_STR will consume. We therefore generate a valid text line payload
# suitable for COPY IN text mode: a line optionally ending with a newline, and
# without embedded NULs.
# - Keep under 4096 bytes.

ASCII_VISIBLE = (
    [" ", "\t"] +
    list(string.digits) +
    list(string.ascii_letters) +
    list("_:-.,;|/\\!@#$%^&*()+={}[]<>?`~'\"")
)

# A small set of multi-byte UTF-8 sequences to exercise encoding paths.
UTF8_SNIPPETS = [
    "αβγ",           # Greek
    "тест",          # Cyrillic
    "漢字かなカナ",    # CJK mix
    "😀🐘🍀",         # Emoji
    "€£¥₩",          # Currency
    "¡¿ñÑçÇ",        # Latin-1 supplement
]

# COPY text mode can see escapes when standard_conforming_strings=off.
ESCAPE_SEQUENCES = ["\\N", "\\t", "\\n", "\\r", "\\\\", "\\000", "\\377"]

CSV_FIELDS = [
    "id", "name", "value", "comment", "timestamp", "null", "true", "false",
]

def _weighted_choice(r: random.Random, items):
    return items[r.randrange(len(items))]

def _gen_ascii_chunk(r: random.Random, min_len: int, max_len: int) -> str:
    n = r.randint(min_len, max_len)
    return "".join(_weighted_choice(r, ASCII_VISIBLE) for _ in range(n))

def _gen_utf8_chunk(r: random.Random) -> str:
    # Mix small ASCII with a chosen UTF-8 snippet
    left = _gen_ascii_chunk(r, 0, 8)
    mid = _weighted_choice(r, UTF8_SNIPPETS)
    right = _gen_ascii_chunk(r, 0, 8)
    return left + mid + right

def _gen_csv_line(r: random.Random) -> str:
    # Produce a CSV-like line with commas and quotes
    cols = r.randint(2, 8)
    fields: List[str] = []
    for _ in range(cols):
        base = _weighted_choice(r, CSV_FIELDS)
        if r.random() < 0.5:
            suffix = _gen_ascii_chunk(r, 0, 6)
            val = base + suffix
        else:
            val = base
        # Occasionally quote and include comma/quote inside
        if r.random() < 0.5:
            val = val.replace('"', '""')  # CSV escape by doubling quotes
            # Construct a quoted field, optionally embedding a comma
            inner = val
            if r.random() < 0.3:
                inner = inner + ","
            val = '"' + inner + '"'
        fields.append(val)
    return ",".join(fields)

def _gen_copy_text_fields(r: random.Random) -> str:
    # Tab-separated values typical for COPY text
    cols = r.randint(1, 10)
    parts = []
    for _ in range(cols):
        choice = r.random()
        if choice < 0.15:
            parts.append("\\N")  # NULL marker
        elif choice < 0.35:
            parts.append(_gen_ascii_chunk(r, 0, 16))
        elif choice < 0.6:
            parts.append(_gen_utf8_chunk(r))
        elif choice < 0.8:
            parts.append(_weighted_choice(r, ESCAPE_SEQUENCES))
        else:
            # Backslash-escaped tabs/newlines inside field
            s = _gen_ascii_chunk(r, 1, 8)
            if r.random() < 0.5:
                s += "\\t"
            if r.random() < 0.3:
                s += "\\n"
            parts.append(s)
    return "\t".join(parts)

def _maybe_newline(r: random.Random) -> str:
    p = r.random()
    if p < 0.5:
        return "\n"
    elif p < 0.65:
        return "\r\n"
    else:
        return ""  # no newline

def _trim_to_limit(s: str, limit: int = 4096) -> str:
    if len(s.encode('utf-8')) <= limit:
        return s
    # Trim by characters but ensure we don't break UTF-8 by encoding after trim
    cut = min(len(s), limit)
    while cut > 0:
        b = s[:cut].encode('utf-8', errors='ignore')
        if len(b) <= limit:
            return b.decode('utf-8', errors='ignore')
        cut -= 1
    return ""  # fallback

def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Choose a scenario to diversify content
    scenario = r.choices(
        population=[
            "empty", "ascii_short", "ascii_long", "utf8", "csv", "copy_text",
            "numbers", "whitespace", "jsonish", "sqlish"
        ],
        weights=[5, 15, 10, 12, 8, 15, 8, 6, 10, 11],
        k=1,
    )[0]

    if scenario == "empty":
        line = ""
    elif scenario == "ascii_short":
        line = _gen_ascii_chunk(r, 1, 64)
    elif scenario == "ascii_long":
        line = _gen_ascii_chunk(r, 256, 2048)
    elif scenario == "utf8":
        chunks = [
            _gen_utf8_chunk(r) for _ in range(r.randint(1, 6))
        ]
        sep = _weighted_choice(r, [" ", "\t", ", ", " | "])
        line = sep.join(chunks)
    elif scenario == "csv":
        line = _gen_csv_line(r)
    elif scenario == "copy_text":
        line = _gen_copy_text_fields(r)
    elif scenario == "numbers":
        nums = [str(r.randint(-2**31, 2**31 - 1)) for _ in range(r.randint(1, 12))]
        line = _weighted_choice(r, [",", "\t", " "]).join(nums)
    elif scenario == "whitespace":
        # Leading/trailing spaces and tabs
        line = (" " * r.randint(0, 8)) + _gen_ascii_chunk(r, 0, 32) + ("\t" * r.randint(0, 8))
    elif scenario == "jsonish":
        # JSON-like content without NULs
        key = _gen_ascii_chunk(r, 3, 10).replace('"', '')
        val = _gen_utf8_chunk(r).replace('"', '\\"')
        line = '{"' + key + '": "' + val + '"}'
    elif scenario == "sqlish":
        # SQL INSERT-like values list
        parts = []
        for _ in range(r.randint(2, 8)):
            t = r.random()
            if t < 0.25:
                parts.append("NULL")
            elif t < 0.55:
                s = _gen_ascii_chunk(r, 0, 10).replace("'", "''")
                parts.append("'" + s + "'")
            elif t < 0.8:
                parts.append(str(r.randint(-10**12, 10**12)))
            else:
                parts.append(str(r.random()))
        line = "(" + ", ".join(parts) + ")"
    else:
        line = _gen_ascii_chunk(r, 1, 32)

    # Append optional newline(s) to form a complete line for line-oriented COPY
    line += _maybe_newline(r)

    # Ensure no embedded NULs
    if "\x00" in line:
        line = line.replace("\x00", "")

    # Enforce total size limit
    line = _trim_to_limit(line, 4096)

    # Return as UTF-8 bytes
    return line.encode('utf-8')
